+func (s *Store) Reserve(ctx context.Context, sku string, n int) error {
+    var stock int
+    if err := s.db.QueryRowContext(ctx, `SELECT stock FROM items WHERE sku=$1`, sku).Scan(&stock); err != nil { return err }
+    if stock < n { return ErrOutOfStock }
+    _, err := s.db.ExecContext(ctx, `UPDATE items SET stock=$1 WHERE sku=$2`, stock-n, sku)
+    return err
+}
